+</head>
+<body>
+<div id="app">
+  <header>
+    <div class="brand">
+      <div class="badge">M</div>
+      <h1>Muse Spark 1.3<small>2D CRASH LAB &middot; CAR vs BRICK WALL</small></h1>
+    </div>
+    <div class="controls">
+      <span class="status-pill" id="statusPill">Staged</span>
+      <button id="testBtn" title="Reset to current settings and launch (Space)">TEST</button>
+      <button id="resetBtn" title="Rebuild staged scene (R)">Reset</button>
