+
+  <div id="main">
+    <div id="stageWrap">
+      <canvas id="stage"></canvas>
+      <div id="telemetry">
+        <div class="tcard"><span>Car speed</span><b id="tSpeed">0.0 m/s</b></div>
+        <div class="tcard"><span>Elapsed</span><b id="tTime">0.00 s</b></div>
+        <div class="tcard"><span>Moving bricks</span><b id="tMoving">0</b></div>
+        <div class="tcard"><span>Car x</span><b id="tCarX">0.0 m</b></div>
+        <div class="tcard"><span>Wall standing</span><b id="tStand">100%</b></div>
+        <div class="tcard"><span>FPS</span><b id="tFps">60</b></div>
+      </div>
+    </div>
+
+    <aside>
+      <h2>Experiment setup</h2>
+      <div class="param">
+        <div class="row"><label for="carSpeed">Car speed</label><output id="oSpeed">22.0 m/s</output></div>
+        <input type="range" id="carSpeed" min="5" max="45" step="0.5" value="22">
+        <div class="hint">5 &ndash; 45 m/s &middot; launch speed after acceleration</div>
+      </div>
+      <div class="param">
+        <div class="row"><label for="wallCols">Wall columns</label><output id="oCols">12</output></div>
+        <input type="range" id="wallCols" min="4" max="24" step="1" value="12">
+        <div class="hint">4 &ndash; 24 bricks across</div>
+      </div>
+      <div class="param">
+        <div class="row"><label for="wallRows">Wall rows</label><output id="oRows">8</output></div>
+        <input type="range" id="wallRows" min="3" max="16" step="1" value="8">
+        <div class="hint">3 &ndash; 16 bricks tall</div>
+      </div>
+      <div class="param">
+        <div class="row"><label for="wallLayers">Wall depth layers</label><output id="oLayers">2</output></div>
+        <input type="range" id="wallLayers" min="1" max="5" step="1" value="2">
+        <div class="hint">1 &ndash; 5 &middot; extruded depth, mass scales &times;layers</div>
+      </div>
+      <div class="param">
+        <div class="row"><label for="brickMass">Brick mass</label><output id="oBrickMass">2.50 kg</output></div>
+        <input type="range" id="brickMass" min="0.5" max="12" step="0.1" value="2.5">
+        <div class="hint">0.5 &ndash; 12 kg per brick layer</div>
+      </div>
+
+      <details>
+        <summary>Advanced physics</summary>
+        <div class="param" style="margin-top:8px">
+          <div class="row"><label for="gravity">Gravity</label><output id="oGravity">9.81 m/s&sup2;</output></div>
+          <input type="range" id="gravity" min="1" max="25" step="0.01" value="9.81">
+        </div>
+        <div class="param">
+          <div class="row"><label for="brickFric">Brick friction &mu;</label><output id="oBrickFric">0.72</output></div>
+          <input type="range" id="brickFric" min="0" max="1.2" step="0.01" value="0.72">
+        </div>
+        <div class="param">
+          <div class="row"><label for="brickRest">Brick restitution</label><output id="oBrickRest">0.18</output></div>
+          <input type="range" id="brickRest" min="0" max="0.9" step="0.01" value="0.18">
+        </div>
+        <div class="param">
+          <div class="row"><label for="carMass">Car mass</label><output id="oCarMass">1250 kg</output></div>
+          <input type="range" id="carMass" min="600" max="2500" step="10" value="1250">
+        </div>
+        <div class="param">
+          <div class="row"><label for="groundFric">Ground friction &mu;</label><output id="oGroundFric">0.85</output></div>
+          <input type="range" id="groundFric" min="0.1" max="1.4" step="0.01" value="0.85">
+        </div>
+      </details>
+
+      <h2>Live readout</h2>
+      <div class="kv"><span>State</span><b id="kvState">staged</b></div>
+      <div class="kv"><span>Car momentum</span><b id="kvMom">0 kg&middot;m/s</b></div>
+      <div class="kv"><span>Car kinetic energy</span><b id="kvKe">0 J</b></div>
+      <div class="kv"><span>Bricks simulated</span><b id="kvBricks">96</b></div>
+      <div class="kv"><span>Peak impact decel</span><b id="kvDecel">0 g</b></div>
+      <div class="kv"><span>Run seed</span><b>deterministic</b></div>
+      <div class="wallmass" id="wallMassBox">Wall: 12 &times; 8 &times; 2 layers &middot; 480 kg total</div>
+      <p class="note">
+        Fixed-step (240 Hz) rigid-body solver with sequential impulses, Coulomb friction and
+        restitution. Depth layers are homogenized out of plane: each in-plane brick carries
+        &times;layers mass and renders extruded depth. Same settings &rarr; same outcome.
+        Dust, shake and skid marks are visual only and never feed back into physics.
+      </p>
+      <p class="note"><kbd>Space</kbd> test &middot; <kbd>R</kbd> reset &middot; deterministic baseline:
+        22 m/s, 12&times;8&times;2, 2.5 kg/brick.</p>
+    </aside>
+  </div>
+
+  <footer>
+    <span>Fixed baseline &mdash; <b>car 4.2 &times; 1.45 m, 1250 kg</b> &middot; <b>brick 0.50 &times; 0.24 m</b> &middot; <b>scale 80 px/m</b> &middot; <b>g 9.81</b> &middot; <b>&mu; brick 0.72 / ground 0.85</b> &middot; <b>e 0.18</b></span>
+    <span id="footMsg">Stage the wall, then press TEST.</span>
+  </footer>
+</div>
+
+<script>
+"use strict";
+/* ============================================================
+   Muse Spark 1.3 — 2D Crash Lab
+   Deterministic fixed-step rigid-body sandbox (no dependencies).
+   - Units: meters, kilograms, seconds. Render scale 80 px/m.
+   - Bodies: oriented boxes (car + bricks). Ground = y=0 plane.
+   - Solver: semi-implicit Euler + sequential impulses (normal
+     with restitution, clamped Coulomb friction) + Baumgarte
+     positional correction + uniform-grid broadphase + sleeping.
+   - Depth layers: homogenized out of plane (mass x layers).
+   ============================================================ */
+
+// ---------- mandatory defaults ----------
+const DEFAULTS = {
+  carSpeed: 22, wallCols: 12, wallRows: 8, wallLayers: 2,
+  brickMass: 2.5, brickW: 0.50, brickH: 0.24,
+  gravity: 9.81, brickFric: 0.72, brickRest: 0.18,
+  carMass: 1250, carW: 4.2, carH: 1.45,
+  groundFric: 0.85, scale: 80
+};
+const LIMITS = {
+  carSpeed:[5,45], wallCols:[4,24], wallRows:[3,16],
+  wallLayers:[1,5], brickMass:[0.5,12]
+};
+
+const settings = {
+  carSpeed: DEFAULTS.carSpeed, wallCols: DEFAULTS.wallCols,
+  wallRows: DEFAULTS.wallRows, wallLayers: DEFAULTS.wallLayers,
+  brickMass: DEFAULTS.brickMass, gravity: DEFAULTS.gravity,
+  brickFric: DEFAULTS.brickFric, brickRest: DEFAULTS.brickRest,
+  carMass: DEFAULTS.carMass, groundFric: DEFAULTS.groundFric
+};
+
+// ---------- tiny helpers ----------
+const clamp = (v,a,b)=> v<a?a : v>b?b : v;
+const TAU = Math.PI*2;
+
+// ---------- world state ----------
+const H = 1/240;                 // fixed physics step
+let bodies = [];                 // all dynamic bodies
+let car = null;
+let wallProto = [];              // staged spawn transforms (deterministic)
+let wallFrontX = 16, wallCenterX = 19, carStartX = 3;
+let phase = "staged";            // staged|drive|settle|settled|paused(overlay)
+let paused = false;
+let elapsed = 0, acc = 0, lastT = 0;
+let engineOn = false, impacted = false;
+let impactEnergy = 0;            // cumulative car contact impulse (visual crumple)
+let peakDecel = 0, prevCarVx = 0;
+let shake = 0;                   // visual-only camera shake energy 0..1
+let camX = 8, wheelSpin = 0;
+let particles = [];              // visual-only dust/debris
+let skids = [];                  // visual-only tire marks {x0,x1,y,alpha}
+let fpsCount = 0, fpsShown = 60, fpsT = 0;
+let bodySeq = 0;
+
+function makeBody(kind,x,y,w,h,mass,fric,rest){
+  const I = mass*(w*w+h*h)/12;
+  return { id:bodySeq++, kind, x,y,a:0, vx:0,vy:0,va:0,
+    hw:w/2, hh:h/2, mass, invM:1/mass, invI:1/I,
+    fric, rest, sleep:0, sleeping:false, seed:x*13.7+y*7.3 };
+}
+
+// Deterministic staged wall layout (identical every reset for same settings)
+function layoutWall(){
+  wallProto = [];
+  const bw = DEFAULTS.brickW, bh = DEFAULTS.brickH, gap = 0.002;
+  const C = settings.wallCols, R = settings.wallRows;
+  const mPer = settings.brickMass * settings.wallLayers;
+  wallFrontX = 16;
+  for(let r=0;r<R;r++){
+    const y = bh/2 + r*(bh+gap);
+    const stagger = (r%2) ? bw/2 : 0;
+    for(let c=0;c<C;c++){
+      const x = wallFrontX + bw/2 + c*(bw+gap) + stagger - bw/4;
+      wallProto.push({x,y,m:mPer});
+    }
+  }
+  wallCenterX = wallFrontX + (C*bw)/2;
+}
+
+function buildScene(){
+  bodies = []; bodySeq = 0;
+  particles = []; skids = [];
+  elapsed = 0; acc = 0; impactEnergy = 0; peakDecel = 0;
+  shake = 0; wheelSpin = 0; impacted = false; engineOn = false;
+  layoutWall();
+  // car: bottom edge rests on ground (y = h/2)
+  car = makeBody("car", carStartX, DEFAULTS.carH/2,
+    DEFAULTS.carW, DEFAULTS.carH, settings.carMass, 0.95, 0.04);
+  car.startX = carStartX;
+  bodies.push(car);
+  for(const p of wallProto){
+    const b = makeBody("brick", p.x, p.y, DEFAULTS.brickW, DEFAULTS.brickH,
+      p.m, settings.brickFric, settings.brickRest);
+    b.homeX = p.x; b.homeY = p.y;
+    bodies.push(b);
+  }
+  prevCarVx = 0;
+  camX = clamp((car.x + wallCenterX)/2 - 2.5, 4, Math.max(4, wallCenterX-6));
+  updateWallBox();
+}
+
+// ---------- collision helpers ----------
+function cornersOf(b){
+  const c = Math.cos(b.a), s = Math.sin(b.a);
+  const pts = [];
+  const local = [[b.hw,b.hh],[ -b.hw,b.hh],[-b.hw,-b.hh],[b.hw,-b.hh]];
+  for(let i=0;i<4;i++){
+    const lx = local[i][0], ly = local[i][1];
+    pts.push([b.x + lx*c - ly*s, b.y + lx*s + ly*c]);
+  }
+  return pts;
+}
+function aabbOf(b){
+  const pts = cornersOf(b);
+  let x0=1e9,x1=-1e9,y0=1e9,y1=-1e9;
+  for(const p of pts){
+    if(p[0]<x0)x0=p[0]; if(p[0]>x1)x1=p[0];
+    if(p[1]<y0)y0=p[1]; if(p[1]>y1)y1=p[1];
+  }
+  return [x0,y0,x1,y1];
+}
+function pointInBody(b,px,py){
+  const dx = px-b.x, dy = py-b.y;
+  const c = Math.cos(-b.a), s = Math.sin(-b.a);
+  const lx = dx*c - dy*s, ly = dx*s + dy*c;
+  return Math.abs(lx) <= b.hw+1e-9 && Math.abs(ly) <= b.hh+1e-9;
+}
+
+// SAT box-box. Returns null or {nx,ny,pen}
+function satCollide(A,B){
+  const axes = [];
+  for(const b of [A,B]){
+    const c=Math.cos(b.a), s=Math.sin(b.a);
+    axes.push([c,s]); axes.push([-s,c]);
+  }
+  const cA = cornersOf(A), cB = cornersOf(B);
+  let best = 1e9, bn = null;
+  for(const ax of axes){
+    let mna=1e9,mxa=-1e9,mnb=1e9,mxb=-1e9;
+    for(const p of cA){ const d=p[0]*ax[0]+p[1]*ax[1]; if(d<mna)mna=d; if(d>mxa)mxa=d; }
+    for(const p of cB){ const d=p[0]*ax[0]+p[1]*ax[1]; if(d<mnb)mnb=d; if(d>mxb)mxb=d; }
+    const ov = Math.min(mxa,mxb)-Math.max(mna,mnb);
+    if(ov <= 0) return null;
+    if(ov < best){
+      best = ov;
+      // orient normal from A toward B
+      const dABx = B.x-A.x, dABy = B.y-A.y;
+      const sgn = (dABx*ax[0]+dABy*ax[1]) >= 0 ? 1 : -1;
+      bn = [ax[0]*sgn, ax[1]*sgn];
+    }
+  }
+  return {nx:bn[0], ny:bn[1], pen:best};
+}
+
+function contactPoint(A,B,nx,ny){
+  // average of vertices of each box inside the other (stable for face contacts)
+  let sx=0, sy=0, n=0;
+  for(const p of cornersOf(A)) if(pointInBody(B,p[0],p[1])){ sx+=p[0]; sy+=p[1]; n++; }
+  for(const p of cornersOf(B)) if(pointInBody(A,p[0],p[1])){ sx+=p[0]; sy+=p[1]; n++; }
+  if(n>0) return [sx/n, sy/n];
+  // edge-edge fallback: deepest support midpoint
+  let dA=-1e9,pA=null,dB=-1e9,pB=null;
+  for(const p of cornersOf(A)){ const d=-(p[0]*nx+p[1]*ny); if(d>dA){dA=d;pA=p;} }
+  for(const p of cornersOf(B)){ const d=(p[0]*nx+p[1]*ny); if(d>dB){dB=d;pB=p;} }
+  return [(pA[0]+pB[0])/2,(pA[1]+pB[1])/2];
+}
+
+function applyImpulse(A,B,px,py,nx,ny,rest,mu,isGround){
+  const rax=px-A.x, ray=py-A.y;
+  const rbx=isGround?0:px-B.x, rby=isGround?0:py-B.y;
+  const vAx=A.vx - A.va*ray, vAy=A.vy + A.va*rax;
+  let vBx=0, vBy=0;
+  if(!isGround){ vBx=B.vx - B.va*rby; vBy=B.vy + B.va*rbx; }
+  const rvx=vBx-vAx, rvy=vBy-vAy;
+  const vn = rvx*nx + rvy*ny;
+  if(vn >= 0) return 0;
+  const raCn = rax*ny - ray*nx, rbCn = isGround?0:(rbx*ny - rby*nx);
+  const invMA=A.invM, invMB=isGround?0:B.invM;
+  const invIA=A.invI, invIB=isGround?0:B.invI;
+  const kn = invMA+invMB + raCn*raCn*invIA + rbCn*rbCn*invIB;
+  // restitution only for genuinely fast impacts (kills rest jitter)
+  const e = vn < -1.2 ? rest : 0;
+  const j = -(1+e)*vn/kn;
+  const ix=j*nx, iy=j*ny;
+  A.vx-=ix*invMA; A.vy-=iy*invMA; A.va-=(rax*iy-ray*ix)*invIA;
+  if(!isGround){ B.vx+=ix*invMB; B.vy+=iy*invMB; B.va+=(rbx*iy-rby*ix)*invIB; }
+  // friction
+  const tx=-ny, ty=nx;
+  const vAx2=A.vx - A.va*ray, vAy2=A.vy + A.va*rax;
+  let vBx2=0,vBy2=0;
+  if(!isGround){ vBx2=B.vx - B.va*rby; vBy2=B.vy + B.va*rbx; }
+  const vt=(vBx2-vAx2)*tx+(vBy2-vAy2)*ty;
+  const kt=invMA+invMB+Math.pow(rax*ty-ray*tx,2)*invIA+(isGround?0:Math.pow(rbx*ty-rby*tx,2)*invIB);
+  let jt=-vt/kt;
+  const maxF=mu*Math.abs(j);
+  jt=clamp(jt,-maxF,maxF);
+  A.vx-=jt*tx*invMA; A.vy-=jt*ty*invMA; A.va-=(rax*(jt*ty)-ray*(jt*tx))*invIA;
+  if(!isGround){ B.vx+=jt*tx*invMB; B.vy+=jt*ty*invMB; B.va+=(rbx*(jt*ty)-rby*(jt*tx))*invIB; }
+  return j;
+}
+
+function positionalCorrect(A,B,nx,ny,pen,isGround){
+  const slop=0.0012, pct=0.38;
+  const corr=Math.max(pen-slop,0)*pct;
+  if(corr<=0) return;
+  if(isGround){
+    // push body up; tilt slightly toward deepest corner for natural lean
+    A.y += corr;
+    if(A.kind!=="car") A.a += clamp(-A.a*0.002, -0.002, 0.002);
+  } else {
+    const w = A.invM+B.invM;
+    if(w<=0) return;
+    const ca=corr*A.invM/w, cb=corr*B.invM/w;
+    A.x-=nx*ca; A.y-=ny*ca;
+    B.x+=nx*cb; B.y+=ny*cb;
+  }
+}
+
+// ---------- broadphase grid ----------
+function broadPairs(){
+  const cell=1.1, map=new Map();
+  const keys=new Array(bodies.length);
+  for(let i=0;i<bodies.length;i++){
+    const b=bodies[i];
+    if(b.sleeping) continue;
+    const k=Math.floor(b.x/cell)+":"+Math.floor(b.y/cell);
+    keys[i]=k;
+    if(!map.has(k)) map.set(k,[]);
+    map.get(k).push(i);
+  }
+  const pairs=[];
+  const seen=new Set();
+  for(let i=0;i<bodies.length;i++){
+    const b=bodies[i];
+    if(b.sleeping) continue;
+    const cx=Math.floor(b.x/cell), cy=Math.floor(b.y/cell);
+    for(let dx=-1;dx<=1;dx++) for(let dy=-1;dy<=1;dy++){
+      const arr=map.get((cx+dx)+":"+(cy+dy));
+      if(!arr) continue;
+      for(const j of arr){
+        if(j<=i) continue;
+        const key=i+"_"+j;
+        if(seen.has(key)) continue;
+        seen.add(key);
+        const A=bodies[i], B=bodies[j];
+        // quick AABB reject with margin
+        if(Math.abs(A.x-B.x) > (A.hw+A.hh+B.hw+B.hh)+0.05) continue;
+        if(Math.abs(A.y-B.y) > (A.hw+A.hh+B.hw+B.hh)+0.05) continue;
+        pairs.push([A,B]);
+      }
+    }
+  }
+  return pairs;
+}
+
+// ---------- one fixed physics step ----------
+function physicsStep(h){
+  const g = settings.gravity;
+  const ENGINE_A = 13.5;
+  for(const b of bodies){
+    if(b.sleeping) continue;
+    b.vy -= g*h;
+    // engine + rolling resistance for car
+    if(b.kind==="car"){
+      if(engineOn && phase==="drive"){
+        if(b.vx < settings.carSpeed) b.vx = Math.min(settings.carSpeed, b.vx + ENGINE_A*h);
+      } else if(phase==="drive" || phase==="settle"){
+        // rolling drag + aero (keeps coasting honest)
+        b.vx -= b.vx*0.012*h + Math.sign(b.vx)*Math.min(Math.abs(b.vx), 0.25*h);
+      }
+      b.va *= (1-0.6*h);
+    } else {
+      b.vx *= (1-0.008*h); b.vy *= (1-0.002*h); b.va *= (1-0.25*h);
+    }
+    // wake neighbors of fast bodies handled in narrowphase; integrate
+    b.x += b.vx*h; b.y += b.vy*h; b.a += b.va*h;
+    if(b.a>Math.PI)b.a-=TAU; if(b.a<-Math.PI)b.a+=TAU;
+  }
+
+  const pairs = broadPairs();
+  const ITER = 9;
+  for(let it=0; it<ITER; it++){
+    // ground contacts
+    for(const b of bodies){
+      if(b.sleeping) continue;
+      const pts = cornersOf(b);
+      let deepest = 0, cxp=0, cyp=0, cn=0;
+      for(const p of pts){
+        if(p[1] < 0){
+          const pen=-p[1];
+          if(pen>deeper(deepest,pen)){ deepest=pen; }
+          cxp+=p[0]; cyp+=0; cn++;
+        }
+      }
+      if(cn>0){
+        const mu=(b.fric+settings.groundFric)/2;
+        applyImpulse(b,null,cxp/cn,0,0,1,b.kind==="car"?0.02:Math.min(b.rest,0.25),mu,true);
+        if(it===ITER-1) positionalCorrect(b,null,0,1,deepest,true);
+      }
+    }
+    // body-body contacts
+    for(const pr of pairs){
+      const A=pr[0], B=pr[1];
+      if(A.sleeping && B.sleeping) continue;
+      const hit=satCollide(A,B);
+      if(!hit) continue;
+      // wake up sleepers on real contact
+      A.sleeping=false; B.sleeping=false; A.sleep=0; B.sleep=0;
+      const cp=contactPoint(A,B,hit.nx,hit.ny);
+      const mu=Math.sqrt(Math.max(0.01,A.fric)*Math.max(0.01,B.fric));
+      const rest=Math.max(A.rest,B.rest)*0.6 + Math.min(A.rest,B.rest)*0.4;
+      const j=applyImpulse(A,B,cp[0],cp[1],hit.nx,hit.ny,Math.min(rest,0.4),mu,false);
+      if(it===ITER-1) positionalCorrect(A,B,hit.nx,hit.ny,hit.pen,false);
+      // car impact bookkeeping on first iterations only
+      if(it===0 && (A.kind==="car"||B.kind==="car") && Math.abs(j)>40){
+        const carB = A.kind==="car"?A:B;
+        onCarImpact(Math.abs(j), cp[0], cp[1], carB);
+      }
+      if(it===0 && Math.abs(j)>120){
+        spawnDust(cp[0],cp[1],Math.min(10,Math.abs(j)/900));
+      }
+    }
+    void deeper;
+  }
+  function deeper(a,b){ return b; }
+
+  // sleeping + settle bookkeeping
+  let moving=0;
+  for(const b of bodies){
+    if(b.kind==="car") continue;
+    const sp=Math.hypot(b.vx,b.vy)+Math.abs(b.va)*0.4;
+    if(sp<0.09 && b.y<3.5){ b.sleep++; if(b.sleep>50){ b.sleeping=true; b.vx=b.vy=b.va=0; } }
+    else { b.sleep=0; }
+    if(sp>0.28) moving++;
+  }
+  movingBricks=moving;
+
+  // car ground stick: never tunnel below ground through solver gaps
+  if(car.y < car.hh-0.02 && Math.abs(car.va)<2){ car.y = Math.max(car.y, car.hh-0.02); }
+
+  // phases + telemetry extremes
+  const decel = Math.abs(car.vx-prevCarVx)/h/9.81;
+  prevCarVx = car.vx;
+  if(impacted && decel>peakDecel && decel<400) peakDecel=decel;
+
+  if(phase==="drive"){
+    if(impacted && Math.abs(car.vx)<0.4 && moving<3) settleTimer+=h; else settleTimer=0;
+    const allSlow = Math.abs(car.vx)<0.35 && moving<2;
+    if(allSlow){ stillTimer+=h; } else stillTimer=0;
+    if(stillTimer>0.9 && elapsed>1.2){ phase="settled"; setStatus("settled"); }
+    else if(impacted) { if(phase!=="settle"){phase="settle"; setStatus("settling");} }
+  }
+  if(phase==="drive" && !impacted && car.x > wallFrontX-0.5 && elapsed>0.4){
+    // touched wall region: engine cut handled in onCarImpact; safety cutoff
+    if(car.x > wallFrontX + 0.4) engineOn=false;
+  }
+  wheelSpin += (car.vx*h)/0.34;
+}
+let movingBricks=0, settleTimer=0, stillTimer=0;
+
+// visual-only impact feedback (never touches solver state except shake/counters)
+function onCarImpact(j,px,py,carB){
+  if(!impacted){
+    impacted=true; engineOn=false;
+    if(phase==="drive"){ phase="settle"; setStatus("impact"); }
+    setTimeout(()=>{ if(phase==="settle") setStatus("settling"); }, 900);
+  }
+  impactEnergy += j;
+  shake = clamp(shake + Math.min(0.85, j/9000), 0, 1);
+  // skid mark at first heavy contact
+  if(j>1500 && skids.length<240){
+    skids.push({x0:carB.x-carB.hw, x1:carB.x-carB.hw+0.6, y:0.02, alpha:0.55});
+  }
+  spawnDust(px,py,clamp(j/4500,1.5,9));
+}
+
+// ---------- dust (visual only) ----------
+function spawnDust(x,y,n){
+  for(let i=0;i<n;i++){
+    if(particles.length>420) particles.shift();
+    const a=Math.random()*Math.PI - Math.PI*0.05;   // mostly upward/outward
+    const sp=0.6+Math.random()*2.6;
+    particles.push({x:x+(Math.random()-0.5)*0.5, y:Math.max(0.05,y+Math.random()*0.3),
+      vx:Math.cos(a)*sp - 1.2 - Math.random()*1.5, vy:Math.abs(Math.sin(a))*sp+0.5+Math.random()*1.4,
+      life:0, max:0.7+Math.random()*0.9, size:2+Math.random()*5});
+  }
+}
+function stepParticles(dt){
+  for(const p of particles){
+    p.life+=dt;
+    p.vy-=1.6*dt; p.vx*=(1-1.4*dt);
+    p.x+=p.vx*dt; p.y=Math.max(0.02,p.y+p.vy*dt);
+  }
+  particles=particles.filter(p=>p.life<p.max);
+}
