+// ============================================================
+//  RENDER
+// ============================================================
+const canvas=document.getElementById("stage");
+const ctx=canvas.getContext("2d");
+let W=800,Hpx=500,DPR=1;
+
+function resize(){
+  const r=canvas.parentElement.getBoundingClientRect();
+  DPR=Math.min(2,window.devicePixelRatio||1);
+  W=Math.max(320,r.width); Hpx=Math.max(280,r.height);
+  canvas.width=Math.round(W*DPR); canvas.height=Math.round(Hpx*DPR);
+  ctx.setTransform(DPR,0,0,DPR,0,0);
+}
+new ResizeObserver(resize).observe(canvas.parentElement);
+window.addEventListener("resize",resize);
+
+const S = ()=> DEFAULTS.scale;   // 80 px/m fixed
+function w2s(wx,wy){
+  const s=S();
+  const shx = shake>0.01 ? Math.sin(elapsed*91.0)*shake*shake*9 : 0;
+  const shy = shake>0.01 ? Math.cos(elapsed*113.0)*shake*shake*7 : 0;
+  return [ (wx-camX)*s + W*0.38 + shx, (groundY()-wy*s) + shy ];
+}
+function groundY(){ return Hpx*0.76; }
+
+function drawBrick(b){
+  const s=S();
+  const [sx,sy]=w2s(b.x,b.y);
