+  const L=settings.wallLayers;
+  ctx.save();
+  ctx.translate(sx,sy); ctx.rotate(-b.a);
+  // depth extrusion (visual thickness to lower-right)
+  const ex=Math.min(14, 2+L*2.4), ey=Math.min(10, 1.5+L*1.6);
+  ctx.fillStyle="rgba(0,0,0,0.35)";
+  roundRect(ctx,-wpx/2+ex,-hpx/2+ey,wpx,hpx,2); ctx.fill();
+  // body with deterministic per-brick tint
+  const t=((b.id*0.37)%1+1)%1;
+  const rC=Math.round(168+t*26), gC=Math.round(74+t*14), bC=Math.round(52+t*10);
+  const grd=ctx.createLinearGradient(0,-hpx/2,0,hpx/2);
+  grd.addColorStop(0,`rgb(${rC+22},${gC+16},${bC+12})`);
+  grd.addColorStop(0.5,`rgb(${rC},${gC},${bC})`);
+  grd.addColorStop(1,`rgb(${rC-26},${gC-18},${bC-14})`);
