+  roundRect(ctx,-wpx/2,-hpx/2,wpx,hpx,2); ctx.fill();
+  ctx.strokeStyle="rgba(20,8,4,0.85)"; ctx.lineWidth=1.2;
+  roundRect(ctx,-wpx/2,-hpx/2,wpx,hpx,2); ctx.stroke();
+  // top highlight + mortar speckle
+  ctx.fillStyle="rgba(255,255,255,0.16)";
+  ctx.fillRect(-wpx/2+2,-hpx/2+1.5,wpx-4,2);
+  ctx.fillStyle="rgba(0,0,0,0.25)";
+  ctx.fillRect(-wpx/2+3,hpx/2-3.5,wpx-6,1.5);
+  // layer striations on the right edge = depth layers
+  if(L>1){
+    ctx.fillStyle="rgba(0,0,0,0.4)";
+    for(let i=1;i<L;i++){
+      const yy=-hpx/2+(hpx/L)*i;
+      ctx.fillRect(-wpx/2+2,yy-0.6,wpx-4,1.2);
