+  // staged ghost outline before first run
+  if(!impacted && (phase==="staged")){
+    ctx.save();
+    ctx.strokeStyle="rgba(77,163,255,0.5)"; ctx.setLineDash([6,5]); ctx.lineWidth=1.5;
+    const [wx0,wy0]=w2s(wallFrontX,settings.wallRows*DEFAULTS.brickH+0.4);
+    const wallWp=settings.wallCols*DEFAULTS.brickW*s+10, wallHp=(settings.wallRows*DEFAULTS.brickH)*s+16;
+    ctx.strokeRect(wx0-6,wy0-8,wallWp,wallHp);
+    ctx.setLineDash([]);
+    ctx.fillStyle="rgba(160,200,255,0.8)"; ctx.font="11px sans-serif";
+    ctx.fillText("WALL "+settings.wallCols+"×"+settings.wallRows+"×"+settings.wallLayers,wx0,wy0-12);
+    ctx.restore();
+  }
+
+  // bricks back-to-front
+  const sorted=[...bodies].filter(b=>b.kind==="brick").sort((a,b2)=>a.x-b2.x);
+  for(const b of sorted) drawBrick(b);
+  drawCar();
+
+  // dust
+  for(const p of particles){
+    const [sx,sy]=w2s(p.x,p.y);
+    const k=1-p.life/p.max;
+    ctx.fillStyle=`rgba(190,175,150,${(0.5*k).toFixed(3)})`;
+    ctx.beginPath(); ctx.arc(sx,sy,p.size*(0.6+ (1-k)*1.6),0,TAU); ctx.fill();
+  }
+
+  // impact flash ring (first 300ms)
+  if(impacted && elapsedSinceImpact()<0.35){
+    const t=elapsedSinceImpact()/0.35;
+    const [ix,iy]=w2s(wallFrontX,1.0);
+    ctx.strokeStyle=`rgba(255,200,120,${(0.8*(1-t)).toFixed(3)})`;
+    ctx.lineWidth=3;
+    ctx.beginPath(); ctx.arc(ix,iy,20+t*90,0,TAU); ctx.stroke();
+  }
+
+  // vignette
+  const vg=ctx.createRadialGradient(W/2,Hpx/2,Hpx*0.35,W/2,Hpx/2,Hpx*0.95);
+  vg.addColorStop(0,"rgba(0,0,0,0)"); vg.addColorStop(1,"rgba(0,0,0,0.42)");
+  ctx.fillStyle=vg; ctx.fillRect(0,0,W,Hpx);
+}
+let impactT=1e9;
+const _origImpact=onCarImpact;
+onCarImpact=function(j,x,y,c){ impactT=elapsed; _origImpact(j,x,y,c); };
+function elapsedSinceImpact(){ return elapsed-impactT; }
+
+// ---------- camera ----------
+function stepCamera(dt){
+  let target;
+  if(phase==="staged") target=(car.x+wallCenterX)/2-2.2;
+  else if(!impacted) target=car.x+4.2;
+  else target=wallCenterX-2.5+(car.x-wallFrontX)*0.12;
+  target=clamp(target,3.5,Math.max(3.5,wallCenterX+2));
+  camX+=(target-camX)*Math.min(1,dt*2.6);
+  shake=Math.max(0,shake-dt*1.5);
+}
+
+// ============================================================
+//  UI
+// ============================================================
+const $=id=>document.getElementById(id);
+const pill=$("statusPill");
+function setStatus(s){
+  const map={staged:["Staged",""],drive:["Running","live"],impact:["Impact","impact"],
+    settling:["Settling","live"],settled:["Settled",""],paused:["Paused",""]};
+  const m=map[s]||[s,""];
+  pill.textContent=m[0]; pill.className="status-pill "+m[1];
+  $("kvState").textContent = phase==="drive"&&!impacted ? (engineOn?"accelerating":"cruising") : s;
+}
+function updateWallBox(){
+  const total=settings.wallCols*settings.wallRows*settings.wallLayers*settings.brickMass;
+  $("wallMassBox").textContent=
+    `Wall: ${settings.wallCols} × ${settings.wallRows} × ${settings.wallLayers} layers · ${settings.wallCols*settings.wallRows} bodies · ${total.toFixed(0)} kg total`;
+  $("kvBricks").textContent=`${settings.wallCols*settings.wallRows} (+×${settings.wallLayers} mass)`;
+}
+function syncOutputs(){
+  $("oSpeed").textContent=settings.carSpeed.toFixed(1)+" m/s";
+  $("oCols").textContent=settings.wallCols;
+  $("oRows").textContent=settings.wallRows;
+  $("oLayers").textContent=settings.wallLayers;
+  $("oBrickMass").textContent=settings.brickMass.toFixed(2)+" kg";
+  $("oGravity").textContent=settings.gravity.toFixed(2)+" m/s²";
+  $("oBrickFric").textContent=settings.brickFric.toFixed(2);
+  $("oBrickRest").textContent=settings.brickRest.toFixed(2);
+  $("oCarMass").textContent=settings.carMass.toFixed(0)+" kg";
+  $("oGroundFric").textContent=settings.groundFric.toFixed(2);
+}
+function bindParam(id,key,parse,after){
+  $(id).addEventListener("input",e=>{
+    let v=parse(e.target.value);
+    const lim=LIMITS[key];
+    if(lim) v=clamp(v,lim[0],lim[1]);
+    settings[key]=v;           // never touches unrelated params
+    syncOutputs(); updateWallBox();
+    if(after) after();
+    stageScene();              // changing settings re-stages deterministically
+  });
+}
+function stageScene(){
+  if(phase==="drive"||phase==="settle") return;  // don't disturb a live run via slider drag
+  buildScene(); phase="staged"; setStatus("staged");
+  $("footMsg").textContent="Staged with current settings. Press TEST.";
+  refreshTelemetry(0);
+}
+bindParam("carSpeed","carSpeed",parseFloat);
+bindParam("wallCols","wallRows",parseFloat); // placeholder guard (rebound below)
+$("wallCols").addEventListener("input",e=>{});
+// Rebind correctly (explicit, independent — no cross-talk):
+(function rebind(){
+  const pairs=[["carSpeed","carSpeed",parseFloat],["wallCols","wallCols",parseInt],
+    ["wallRows","wallRows",parseInt],["wallLayers","wallLayers",parseInt],
+    ["brickMass","brickMass",parseFloat],["gravity","gravity",parseFloat],
+    ["brickFric","brickFric",parseFloat],["brickRest","brickRest",parseFloat],
+    ["carMass","carMass",parseFloat],["groundFric","groundFric",parseFloat]];
+  for(const [id,key,fn] of pairs){
+    // remove previous listeners by cloning
+    const el=$(id), clone=el.cloneNode(true);
+    el.parentNode.replaceChild(clone,el);
+    clone.value = key==="wallCols"?settings.wallCols : key==="wallRows"?settings.wallRows :
+      key==="wallLayers"?settings.wallLayers : settings[key];
+    clone.addEventListener("input",e=>{
+      let v=fn(e.target.value);
+      const lim=LIMITS[key];
+      if(lim) v=clamp(v,lim[0],lim[1]);
+      settings[key]=v;
+      syncOutputs(); updateWallBox();
+      if(phase!=="drive"&&phase!=="settle"){ buildScene(); phase="staged"; setStatus("staged"); refreshTelemetry(0); }
+    });
+  }
+})();
+
+$("testBtn").addEventListener("click",runTest);
+$("resetBtn").addEventListener("click",()=>{
+  paused=false; $("pauseBtn").textContent="Pause";
+  buildScene(); phase="staged"; setStatus("staged");
+  impactT=1e9; $("footMsg").textContent="Reset to current settings.";
+  refreshTelemetry(0);
+});
+$("pauseBtn").addEventListener("click",()=>{
+  paused=!paused;
+  $("pauseBtn").textContent=paused?"Resume":"Pause";
+  if(paused) setStatus("paused");
+  else setStatus(phase==="staged"?"staged":impacted?(phase==="settled"?"settled":"settling"):"drive");
+});
+window.addEventListener("keydown",e=>{
+  if(e.code==="Space" && !/INPUT|BUTTON/.test(document.activeElement.tagName)){ e.preventDefault(); runTest(); }
+  if(e.key==="r"||e.key==="R") $("resetBtn").click();
+});
+
+function runTest(){
+  paused=false; $("pauseBtn").textContent="Pause";
+  buildScene();                 // reset to current settings first (deterministic)
+  impactT=1e9;
+  phase="drive"; engineOn=true; settleTimer=0; stillTimer=0;
+  setStatus("drive");
+  $("kvState").textContent="accelerating";
+  $("footMsg").textContent=`Test running: ${settings.carSpeed.toFixed(1)} m/s into ${settings.wallCols}×${settings.wallRows}×${settings.wallLayers} wall.`;
+}
+
+// ---------- telemetry ----------
+function refreshTelemetry(fps){
+  const v=car?car.vx:0;
+  $("tSpeed").textContent=`${v.toFixed(1)} m/s · ${(Math.abs(v)*3.6).toFixed(0)} km/h`;
+  $("tTime").textContent=`${elapsed.toFixed(2)} s`;
+  $("tMoving").textContent=`${movingBricks}`;
+  $("tCarX").textContent=`${car?car.x.toFixed(1):"0.0"} m`;
+  let standing=0,total=0;
+  for(const b of bodies){
+    if(b.kind!=="brick") continue; total++;
+    const moved=Math.hypot(b.x-b.homeX,b.y-b.homeY);
+    if(moved<0.12 && Math.abs(b.a)<0.12) standing++;
+  }
+  $("tStand").textContent= total? Math.round(100*standing/total)+"%":"—";
+  $("tFps").textContent=`${Math.round(fps)}`;
+  if(car){
+    $("kvMom").textContent=`${Math.round(car.mass*car.vx).toLocaleString()} kg·m/s`;
+    $("kvKe").textContent=`${Math.round(0.5*car.mass*car.vx*car.vx).toLocaleString()} J`;
+  }
+  $("kvDecel").textContent=`${peakDecel.toFixed(1)} g`;
+}
+
+// ---------- main loop ----------
+function frame(t){
+  requestAnimationFrame(frame);
+  if(!lastT) lastT=t;
+  let dt=(t-lastT)/1000; lastT=t;
+  if(dt>0.06) dt=0.06;
+  fpsCount++; fpsT+=dt;
+  if(fpsT>=0.5){ fpsShown=fpsCount/fpsT; fpsCount=0; fpsT=0; }
+
+  if(!paused){
+    if(phase==="drive"||phase==="settle"){
+      acc+=dt;
+      let n=0;
+      while(acc>=H && n<16){ physicsStep(H); elapsed+=H; acc-=H; n++; }
+      if(n===16) acc=0;
+    } else {
+      // staged/settled: gentle settle so the wall rests exactly (deterministic)
+      if(phase==="staged"){
+        // run a few steps once so stacked wall micro-settles identically each reset
+        if(elapsed<0.5){ for(let i=0;i<4;i++){ physicsStep(H); elapsed+=H; } }
+      }
+    }
+    stepParticles(dt);
+    stepCamera(dt);
+    // live skid marks while driving hard
+    if((phase==="drive") && Math.abs(car.vx)>10 && !car.sleeping && skids.length<300){
+      const tail=skids[skids.length-1];
+      if(!tail || Math.abs(tail.x1-car.x)>0.5)
+        skids.push({x0:car.x-2.4,x1:car.x-1.6,y:0.02,alpha:0.30});
+    }
+  }
+  drawScene(dt);
+  refreshTelemetry(fpsShown);
+}
+
+// ---------- boot: staged default scene on first paint ----------
+syncOutputs(); updateWallBox();
+buildScene(); phase="staged"; setStatus("staged");
+resize();
+refreshTelemetry(60);
+requestAnimationFrame(frame);
+</script>
+</body>
+</html>

