// Deterministic running-bond layout with flush ends: even rows are full
// bricks, odd rows start/end with half bricks (no cantilevered overhang,
// so the dry stack is freestanding-stable at any brick mass).
function layoutWall(){
  wallProto = [];
  const bw = DEFAULTS.brickW, bh = DEFAULTS.brickH, gap = 0.002;
  const C = settings.wallCols, R = settings.wallRows;
  const mPer = settings.brickMass * settings.wallLayers;
  wallFrontX = 12;
  for(let r=0;r<R;r++){
    const y = bh/2 + r*(bh+gap);
    if(r%2===0){
      for(let c=0;c<C;c++){
        wallProto.push({x: wallFrontX + bw/2 + c*(bw+gap), y, w: bw, m: mPer});
      }
    } else {
      const hw2 = bw/2;
      wallProto.push({x: wallFrontX + hw2/2, y, w: hw2, m: mPer/2});
      let cx = wallFrontX + hw2 + gap;
      for(let c=0;c<C-1;c++){
        wallProto.push({x: cx + bw/2, y, w: bw, m: mPer});
        cx += bw + gap;
      }
      wallProto.push({x: cx + hw2/2, y, w: hw2, m: mPer/2});
    }
  }
  wallCenterX = wallFrontX + (C*bw)/2;
}

