// Deterministic staggered layout (identical every reset for same settings).
// Full bricks only: even rows start flush, odd rows shift half a brick.
// (Half-brick ends were tested and squeeze out of dry stacks like seeds,
// so full-brick stagger with zigzag ends is the stable choice.)
function layoutWall(){
  wallProto = [];
  const bw = DEFAULTS.brickW, bh = DEFAULTS.brickH, gap = 0.002;
  const C = settings.wallCols, R = settings.wallRows;
  const mPer = settings.brickMass * settings.wallLayers;
  wallFrontX = 12;
  for(let r=0;r<R;r++){
    const y = bh/2 + r*(bh+gap);
    const shift = (r%2) ? bw/2 : 0;
    for(let c=0;c<C;c++){
      wallProto.push({x: wallFrontX + bw/2 + c*(bw+gap) + shift, y, w: bw, m: mPer});
    }
  }
  wallCenterX = wallFrontX + (C*bw)/2 + bw/4;
}

