args.command:
dev-browser <<'EOF'
const page = await browser.getPage("main");
await page.goto("file:///Users/melvynx/Developer/agent-benchmarks/benchmarks/car-crash/2026-09-09-cursor-agent-muse-spark-1-3-high-2/index.html?v=12");
await page.waitForTimeout(800);
await page.click("#pauseBtn");
const rep = await page.evaluate(() => {
  const L = window.__lab;
  L.buildScene();
  const bs = L.bodies.filter(b => b.kind === "brick");
  let minGapX = 1e9, minGapY = 1e9;
  for (let i = 0; i < bs.length; i++) for (let j = i+1; j < bs.length; j++) {
    const A = bs[i], B = bs[j];
    const dx = Math.abs(A.x-B.x), dy = Math.abs(A.y-B.y);
    if (dy < 0.05) minGapX = Math.min(minGapX, dx - (A.hw+B.hw));
    if (dx < 0.2) minGapY = Math.min(minGapY, dy - (A.hh+B.hh));
  }
  for (let s = 0; s < 300; s++) L.physicsStep(1/240);
  let moved = 0, topDx = 0, topN = 0, botDx = 0, botN = 0;
  for (const b of bs) {
    const d = Math.hypot(b.x-b.homeX, b.y-b.homeY);
    if (d > 0.12 || Math.abs(b.a) > 0.12) moved++;
    if (b.homeY > 1.5) { topDx += b.x-b.homeX; topN++; }
    if (b.homeY < 0.3) { botDx += b.x-b.homeX; botN++; }
  }
  return { n: bs.length, minGapX: +minGapX.toFixed(4), minGapY: +minGapY.toFixed(4),
    moved, topDx: +(topDx/topN).toFixed(3), botDx: +(botDx/botN).toFixed(3) };
});
console.log("REP " + JSON.stringify(rep));
EOF

