// Deterministic half-bond layout (identical every reset for same settings).
// Odd rows shift half a brick; the wall recenters so end bricks keep 75%
// support — stable for freestanding dry stacks at any configured mass.
function layoutWall(){
  wallProto = [];
  const bw = DEFAULTS.brickW, bh = DEFAULTS.brickH, gap = 0.002;
  const C = settings.wallCols, R = settings.wallRows;
  const mPer = settings.brickMass * settings.wallLayers;
  wallFrontX = 12;
  for(let r=0;r<R;r++){
    const y = bh/2 + r*(bh+gap);
    const shift = (r%2) ? bw/2 : 0;
    for(let c=0;c<C;c++){
      wallProto.push({x: wallFrontX + bw/2 + c*(bw+gap) + shift - bw/4, y, w: bw, m: mPer});
    }
  }
  wallCenterX = wallFrontX + (C*bw)/2;
}

