// Mortar joints between bricks that start face-to-face. A joint welds its
// pair rigidly until the transmitted impulse exceeds its strength, then it
// fractures permanently — so the freestanding wall is rock solid at any
// height, and crumbles progressively under car impact. Fully deterministic.
let bonds = [];
function buildBonds(){
  bonds = [];
  const K = 260;   // joint strength per meter of seam per depth layer
  const bricks = bodies.filter(b=>b.kind==="brick");
  for(let i=0;i<bricks.length;i++) for(let j=i+1;j<bricks.length;j++){
    const A=bricks[i], B=bricks[j];
    const dx=B.x-A.x, dy=B.y-A.y;
    const ax=Math.abs(dx), ay=Math.abs(dy);
    // stacked pair (vertical seam between rows)
    const pitchY = DEFAULTS.brickH + 0.002;
    if(Math.abs(ay-pitchY)<0.006 && ax < (A.hw+B.hw)*0.8){
      const overlap=(A.hw+B.hw)-ax;
      bonds.push({A,B,nx:0,ny:Math.sign(dy)||1,
        px:(A.x+B.x)/2, py:(A.y+B.y)/2,
        rest:ay, s:Math.max(20, K*overlap*settings.wallLayers), broken:false});
    }
    // side-by-side pair (horizontal seam within a row)
    const pitchX = (A.hw+B.hw)*2 + 0.002;
    if(Math.abs(ax-pitchX)<0.006 && ay < (A.hh+B.hh)*0.8){
      const overlap=(A.hh+B.hh)-ay;
      bonds.push({A,B,nx:Math.sign(dx)||1,ny:0,
        px:(A.x+B.x)/2, py:(A.y+B.y)/2,
        rest:ax, s:Math.max(20, K*overlap*settings.wallLayers), broken:false});
    }
  }
}

function solveBonds(){
  for(const bd of bonds){
    if(bd.broken) continue;
    const A=bd.A, B=bd.B;
    const rax=bd.px-A.x, ray=bd.py-A.y, rbx=bd.px-B.x, rby=bd.py-B.y;
    const vAx=A.vx-A.va*ray, vAy=A.vy+A.va*rax;
    const vBx=B.vx-B.va*rby, vBy=B.vy+B.va*rbx;
    const rvx=vBx-vAx, rvy=vBy-vAy;
    const vn=rvx*bd.nx+rvy*bd.ny, tx=-bd.ny, ty=bd.nx;
    const vt=rvx*tx+rvy*ty;
    const raCn=rax*bd.ny-ray*bd.nx, rbCn=rbx*bd.ny-rby*bd.nx;
    const raCt=rax*ty-ray*tx, rbCt=rbx*ty-rby*tx;
    const kn=A.invM+B.invM+raCn*raCn*A.invI+rbCn*rbCn*B.invI;
    const kt=A.invM+B.invM+raCt*raCt*A.invI+rbCt*rbCt*B.invI;
    const jn=-vn/kn, jt=-vt/kt;
    if(Math.abs(jn)>bd.s || Math.abs(jt)>bd.s*1.4){ bd.broken=true; continue; }
    const inx=jn*bd.nx, iny=jn*bd.ny, itx=jt*tx, ity=jt*ty;
    A.vx-=inx*A.invM+itx*A.invM; A.vy-=iny*A.invM+ity*A.invM;
    A.va-=((rax*iny-ray*inx)+(rax*ity-ray*itx))*A.invI;
    B.vx+=inx*B.invM+itx*B.invM; B.vy+=iny*B.invM+ity*B.invM;
    B.va+=((rbx*iny-rby*inx)+(rbx*ity-rby*itx))*B.invI;
    // keep the joint assembled (positional, split by mass)
    const sep=(B.x-A.x)*bd.nx+(B.y-A.y)*bd.ny-bd.rest;
    const corr=sep*0.4, w=A.invM+B.invM;
    if(w>0 && Math.abs(corr)>1e-6){
      A.x+=bd.nx*corr*A.invM/w; A.y+=bd.ny*corr*A.invM/w;
      B.x-=bd.nx*corr*B.invM/w; B.y-=bd.ny*corr*B.invM/w;
    }
  }
}

  for(const p of wallProto){
