// Mortar joints between bricks that start face-to-face. Each joint is a
// COMPLIANT spring-damper (never a rigid weld, which would fight the contact
// solver) capped at a fracture force: staging loads are newtons, so the
// freestanding wall holds its shape at any height; car impact delivers
// kilonewtons, so joints shatter progressively and the wall crumbles into
// individual bricks and chunks. Fully deterministic.
let bonds = [];
function buildBonds(){
  bonds = [];
  const FBASE = 650;  // fracture force (N) per meter of seam per depth layer
  const bricks = bodies.filter(b=>b.kind==="brick");
  for(let i=0;i<bricks.length;i++) for(let j=i+1;j<bricks.length;j++){
    const A=bricks[i], B=bricks[j];
    const dx=B.x-A.x, dy=B.y-A.y;
    const ax=Math.abs(dx), ay=Math.abs(dy);
    // stacked pair (vertical seam between rows)
    const pitchY = DEFAULTS.brickH + 0.002;
    if(Math.abs(ay-pitchY)<0.006 && ax < (A.hw+B.hw)*0.8){
      const overlap=(A.hw+B.hw)-ax;
      bonds.push({A,B,rx:dx,ry:dy,
        s:Math.max(40, FBASE*overlap*settings.wallLayers), broken:false});
    }
    // side-by-side pair (horizontal seam within a row)
    const pitchX = (A.hw+B.hw) + 0.002;
    if(Math.abs(ax-pitchX)<0.006 && ay < (A.hh+B.hh)*0.8){
      const overlap=(A.hh+B.hh)-ay;
      bonds.push({A,B,rx:dx,ry:dy,
        s:Math.max(40, FBASE*overlap*settings.wallLayers), broken:false});
    }
  }
}

function solveBonds(h){
  const K = 12000, C = 300;   // spring stiffness (N/m) and damping (N·s/m)
  for(const bd of bonds){
    if(bd.broken) continue;
    const A=bd.A, B=bd.B;
    const dx=(B.x-A.x)-bd.rx, dy=(B.y-A.y)-bd.ry;
    const rvx=B.vx-A.vx, rvy=B.vy-A.vy;
    const Fx=-(K*dx+C*rvx), Fy=-(K*dy+C*rvy);
    if(Math.hypot(Fx,Fy)>bd.s){ bd.broken=true; continue; }
    const ix=Fx*h, iy=Fy*h;
    A.vx-=ix*A.invM; A.vy-=iy*A.invM;
    B.vx+=ix*B.invM; B.vy+=iy*B.invM;
  }
}

