function solveBonds(h){
  // Mass-aware stiffness: identical spring dynamics at every brick mass
  // (omega*h ≈ 0.3 always, unconditionally stable), firm enough that a
  // 16-high column sags millimeters, compliant enough to never fight contacts.
  for(const bd of bonds){
    if(bd.broken) continue;
    const A=bd.A, B=bd.B;
    const mEff=(A.mass*B.mass)/(A.mass+B.mass);
    const k=30000*((A.mass+B.mass)/2)/5, c=1.8*Math.sqrt(k*mEff);
    const dx=(B.x-A.x)-bd.rx, dy=(B.y-A.y)-bd.ry;
    const rvx=B.vx-A.vx, rvy=B.vy-A.vy;
    const Fx=-(k*dx+c*rvx), Fy=-(k*dy+c*rvy);
    if(Fx*Fx+Fy*Fy>bd.s*bd.s){ bd.broken=true; continue; }
    const ix=Fx*h, iy=Fy*h;
    A.vx-=ix*A.invM; A.vy-=iy*A.invM;
    B.vx+=ix*B.invM; B.vy+=iy*B.invM;
  }
}

